  "https://staging.crossmint.com/api/2022-06-09/collections/default/nfts";

const app = express();
app.use(express.json());

app.get("/health", (req, res) => {
  res.json({ status: "ok" });
});

app.post("/webhook/purchase", async (req, res) => {
  const requiredFields = [
    "purchaseId",
    "customerEmail",
    "productName",
    "amount",
  ];

  const missingFields = requiredFields.filter(
    (field) => req.body?.[field] === undefined
  );

  if (missingFields.length > 0) {
    return res.status(400).json({
      error: "Missing required fields",
      required: requiredFields,
    });
  }

  const { purchaseId, customerEmail, productName } = req.body;

  const payload = {
    recipient: `email:${customerEmail}:polygon-amoy`,
    metadata: {
      name: `Receipt: ${productName}`,
      description: `Proof of purchase for order ${purchaseId}`,
      image: "https://example.com/receipt.png",
    },
  };

  let actionId = "mock-action";

  try {
    const response = await fetch(CROSSMINT_API_URL, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "x-client-secret": process.env.CROSSMINT_API_KEY || "",
      },
      body: JSON.stringify(payload),
    });

    const responseBody = await response.json().catch(() => null);
    if (responseBody?.id) {
      actionId = responseBody.id;
    }
  } catch (error) {
    // Keep mock-action on failures.
  }

  return res.json({ status: "receipt_minted", purchaseId, actionId });
});

