const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

const run = async () => {
  const report = {
    health_check: false,
    webhook_response: null,
  };

  const serverProcess = spawn("node", [SERVER_PATH], {
    stdio: ["ignore", "pipe", "pipe"],
    env: process.env,
  });

  serverProcess.stdout.on("data", (data) => {
    process.stdout.write(data);
  });

  serverProcess.stderr.on("data", (data) => {
    process.stderr.write(data);
  });

  try {
    await wait(800);

    const healthResponse = await fetch("http://localhost:3000/health");
    if (healthResponse.ok) {
      const healthBody = await healthResponse.json().catch(() => null);
      report.health_check = healthBody?.status === "ok";
    }

    const purchasePayload = {
      purchaseId: "order-123",
      customerEmail: "buyer@example.com",
      productName: "Premium Bundle",
      amount: 199.99,
    };

    const webhookResponse = await fetch(
      "http://localhost:3000/webhook/purchase",
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(purchasePayload),
      }
    );

    report.webhook_response = await webhookResponse
      .json()
      .catch(() => ({ error: "invalid_json" }));
  } catch (error) {
    report.webhook_response = report.webhook_response || {
      error: error.message,
    };
  } finally {
    fs.writeFileSync(REPORT_PATH, JSON.stringify(report, null, 2));

    if (!serverProcess.killed) {
      serverProcess.kill();
    }
  }
};

